const normalizeName = (s) => String(s || '').trim().replace(/\s+/g, ' ').toLowerCase();

async function connect() {
  if (!env.mongoUri) throw new Error('MONGO_URI is not set (check careconnect-backend/.env).');
  mongoose.set('strictQuery', true);
  await mongoose.connect(env.mongoUri);
  console.log(`Connected. Database: ${mongoose.connection.name}   Host: ${mongoose.connection.host}`);
  if (DRY_RUN) console.log('*** DRY RUN - nothing will be written ***');
}

// Picks the hospital to seed: HOSPITAL_ID if given, otherwise the single ACTIVE hospital.
// Never invents an id; refuses to guess when several active hospitals exist.
async function selectHospital() {
  const active = await Hospital.find({ status: 'ACTIVE' }).sort({ createdAt: 1 });
  if (process.env.HOSPITAL_ID) {
    const h = active.find((x) => String(x._id) === process.env.HOSPITAL_ID.trim());
    if (!h) throw new Error(`HOSPITAL_ID ${process.env.HOSPITAL_ID} is not an ACTIVE hospital.`);
    return h;
  }
  if (active.length === 1) return active[0];
  const list = active.map((h) => `  ${h._id}  ${h.name}`).join('\n') || '  (none)';
  throw new Error(`Expected exactly one ACTIVE hospital but found ${active.length}. Set HOSPITAL_ID to one of:\n${list}`);
}

// Map of normalized department name -> Department document for ONE hospital.
async function departmentIndex(hospitalId) {
  const all = await Department.find({ hospitalId }).sort({ createdAt: 1 });
  const map = new Map();
  all.forEach((d) => { const k = normalizeName(d.name); if (!map.has(k)) map.set(k, d); });
  return { map, all };
}

async function run(main) {
  try {
    await connect();
    await main();
  } catch (err) {
    console.error('\nERROR: ' + err.message);
    process.exitCode = 1;
  } finally {
    await mongoose.disconnect();
  }
}

module.exports = { DEMO_EMAIL_DOMAIN, DRY_RUN, DEPARTMENTS, DOCTORS, normalizeName, selectHospital, departmentIndex, run };
